let palette = [
  "#009dff", "#ff4500", "#ffc400", "#8bc34a", "#0051ff", "#926eff",
  "#e75397", "#01b2e8", "#e8441f", "#ff6a00", "#f7a000", "#f4cd00",
  "#54ab1d", "#1b82e6", "#6d5acf", "#dddddd", "#ff437f", "#ff8f35",
  "#4dc268", "#647582", "#f6f6f6", "#028ff5", "#ff99cc", "#22d3ee",
  "#15ad03", "#ff6347", "#ffec99", "#7fff00", "#0077b6", "#b983ff",
  "#fafafa", "#ffcc00", "#3ddc84", "#004c6d", "#e6a6f5", "#ffdab9",
  "#4a90e2", "#9c27b0", "#ffead0", "#d72638", "#ffeb3b", "#2196f3",
];

const n = 500;
const maxH = 500;
const minH = 100;
const maxW = 1000;
const minW = 200;

let seed;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  palette = palette.map((c) => color(c));
  seed = random(10000);
}

function draw() {
  background("#d4d2d5");
  randomSeed(seed);

  let radius = width * 1.2;
  let bEnergy = (window.beatEnergy || 0.0);
  let bassE = (window.bassEnergy || 0.0);
  let midE = (window.midEnergy || 0.0);
  let highE = (window.highEnergy || 0.0);
  let angle = millis() * 0.0001 * (1.0 + bEnergy * 0.8);
  let centerX = 0;
  let centerY = 0;
  let centerZ = -width * 2;
  let camX = cos(angle) * radius;
  let camZ = sin(angle) * radius + centerZ;
  camera(camX, centerY, camZ, centerX, centerY, centerZ, 0, 1, 0);

  ambientLight(80);
  directionalLight(255, 255, 255, -0.5, -1, -0.3);
  pointLight(255, 255, 255, 0, 0, 500);

  noStroke();

  for (let i = 0; i < n; i++) {
    const c = color(random(palette));
    c.setAlpha(map(sin(millis() / 4000 + i), -1, 1, 30, 200) + bEnergy * 50);

    fill(c);
    specularMaterial(c);
    shininess(50);
    ambientMaterial(c);

    const rnd = random() > 0.5 ? 1 : -1;
    const w = random(minW, maxW);
    const h = random(minH, maxH);

    push();
    rotateY((rnd * PI) / 3);

    const timeOffset = millis() / 10;
    const x = ((random(width * 4) + timeOffset) % (width * 4)) - w / 2;

    if (w / 2 - x < 0) {
      translate(rnd * x, random(-height, height), -random(width * 4));
      plane(w, h);
    } else {
      translate(
        rnd * (x / 2 + w / 4),
        random(-height, height),
        -random(width * 4)
      );
      plane(w / 2 + x, h);
    }

    pop();
  }
}



